import React from "react";
import { Link, useHistory, useLocation } from "react-router-dom";
import { Avatar, Typography, Button } from "@mui/material";
import { makeStyles } from "@mui/styles";
import DashboardIcon from "@mui/icons-material/Dashboard";
import PostAddIcon from "@mui/icons-material/PostAdd";
import AddCircleOutlineIcon from "@mui/icons-material/AddCircleOutline";
import ListAltIcon from "@mui/icons-material/ListAlt";
import RateReviewIcon from "@mui/icons-material/RateReview";
import ManageAccountsIcon from "@mui/icons-material/ManageAccounts";
import HomeIcon from "@mui/icons-material/Home";
import ContactPageIcon from "@mui/icons-material/ContactPage";
import PeopleAltIcon from "@mui/icons-material/PeopleAlt";
import { useSelector } from "react-redux";

const useStyles = makeStyles(() => ({
  sidebar: {
    background: "#111111",
    padding: "0",
    margin: "0 auto",
    width: "100%",
    minHeight: "100vh",
    display: "flex",
    flexDirection: "column",
    borderRight: "1px solid rgba(255,255,255,0.06)",
  },

  /* ── Top Profile Block ── */
  profileBlock: {
    background: "linear-gradient(135deg, #1a0000 0%, #2d0000 100%)",
    borderBottom: "2px solid #dc2626",
    padding: "1.5rem 1rem",
    textAlign: "center",
    position: "relative",
  },
  brandBadge: {
    display: "inline-flex",
    alignItems: "center",
    gap: "5px",
    background: "#dc2626",
    color: "#fff",
    fontSize: "0.6rem",
    fontWeight: 800,
    padding: "3px 10px",
    borderRadius: "20px",
    letterSpacing: "2px",
    textTransform: "uppercase",
    marginBottom: "1rem",
  },
  avatarWrap: {
    position: "relative",
    display: "inline-block",
    marginBottom: "0.75rem",
  },
  avatar11: {
    width: "68px !important",
    height: "68px !important",
    border: "3px solid #dc2626 !important",
    boxShadow: "0 0 20px rgba(220,38,38,0.4) !important",
  },
  onlinePip: {
    position: "absolute",
    bottom: "4px",
    right: "4px",
    width: "12px",
    height: "12px",
    borderRadius: "50%",
    background: "#22c55e",
    border: "2px solid #111",
    boxShadow: "0 0 6px #22c55e",
  },
  adminName: {
    fontWeight: "700 !important",
    fontSize: "0.92rem !important",
    color: "#ffffff !important",
    marginBottom: "2px !important",
  },
  adminEmail: {
    fontSize: "0.72rem !important",
    color: "#9ca3af !important",
  },

  /* ── Navigation ── */
  navSection: {
    flex: 1,
    padding: "1rem 0.75rem",
    overflowY: "auto",
  },
  navLabel: {
    color: "#4b5563",
    fontSize: "0.6rem",
    fontWeight: 700,
    letterSpacing: "2px",
    textTransform: "uppercase",
    padding: "0 0.5rem 0.5rem",
    display: "block",
  },
  menuItem: {
    display: "flex",
    alignItems: "center",
    gap: "10px",
    padding: "0.65rem 0.85rem",
    borderRadius: "8px",
    marginBottom: "2px",
    cursor: "pointer",
    transition: "all 0.2s ease",
    position: "relative",
    textDecoration: "none",
    "& svg": {
      color: "#6b7280",
      fontSize: "1.1rem !important",
      flexShrink: 0,
      transition: "color 0.2s ease",
    },
    "&:hover": {
      background: "rgba(220,38,38,0.1)",
      "& svg": { color: "#ef4444" },
      "& $menuText": { color: "#ffffff" },
    },
  },
  menuItemActive: {
    background: "rgba(220,38,38,0.15) !important",
    borderLeft: "3px solid #dc2626",
    "& svg": { color: "#ef4444 !important" },
    "& $menuText": { color: "#ffffff !important", fontWeight: "600 !important" },
  },
  menuText: {
    color: "#9ca3af",
    fontSize: "0.85rem",
    fontWeight: 500,
    transition: "color 0.2s ease",
  },

  /* ── Footer ── */
  footerBlock: {
    padding: "1rem",
    borderTop: "1px solid rgba(255,255,255,0.06)",
  },
  accountBtn: {
    width: "100% !important",
    padding: "0.65rem 1rem !important",
    borderRadius: "8px !important",
    background: "#dc2626 !important",
    color: "#fff !important",
    fontWeight: "600 !important",
    fontSize: "0.82rem !important",
    textTransform: "none !important",
    boxShadow: "0 4px 12px rgba(220,38,38,0.3) !important",
    transition: "all 0.2s ease !important",
    "&:hover": {
      background: "#b91c1c !important",
      boxShadow: "0 6px 18px rgba(220,38,38,0.45) !important",
    },
  },
}));

const menuItems = [
  { to: "/admin/dashboard", icon: <DashboardIcon />, label: "Dashboard" },
  { to: "/", icon: <HomeIcon />, label: "Home" },
  { to: "/admin/products", icon: <PostAddIcon />, label: "Products" },
  { to: "/admin/new/product", icon: <AddCircleOutlineIcon />, label: "Add Product" },
  { to: "/admin/orders", icon: <ListAltIcon />, label: "Orders" },
  { to: "/admin/users", icon: <PeopleAltIcon />, label: "Users" },
  { to: "/admin/reviews", icon: <RateReviewIcon />, label: "Reviews" },
  { to: "/contact", icon: <ContactPageIcon />, label: "Contact" },
];

function Sidebar() {
  const classes = useStyles();
  const { user, loading } = useSelector((state) => state.userData);
  const location = useLocation();
  const history = useHistory();

  return (
    <>
      {!loading && (
        <div className={classes.sidebar}>
          {/* Profile */}
          <div className={classes.profileBlock}>
            <div className={classes.brandBadge}>⚡ Admin Panel</div>
            <div className={classes.avatarWrap}>
              <Avatar
                src={user && user.avatar.url}
                alt="Admin"
                className={classes.avatar11}
              />
              <div className={classes.onlinePip} />
            </div>
            <Typography className={classes.adminName}>{user && user.name}</Typography>
            <Typography className={classes.adminEmail}>{user && user.email}</Typography>
          </div>

          {/* Nav */}
          <div className={classes.navSection}>
            <span className={classes.navLabel}>Navigation</span>
            {menuItems.map((item) => {
              const isActive = location.pathname === item.to;
              return (
                <Link
                  key={item.to}
                  to={item.to}
                  className={`${classes.menuItem} ${isActive ? classes.menuItemActive : ""}`}
                >
                  {item.icon}
                  <span className={classes.menuText}>{item.label}</span>
                </Link>
              );
            })}
          </div>

          {/* Footer */}
          <div className={classes.footerBlock}>
            <Button
              className={classes.accountBtn}
              onClick={() => history.push("/account")}
              startIcon={<ManageAccountsIcon />}
              fullWidth
            >
              My Account
            </Button>
          </div>
        </div>
      )}
    </>
  );
}

export default Sidebar;
